31	export function AuditTrail({
32	  scenarioId,
33	  requirementId,
34	  compact = false,
35	}: {
36	  scenarioId?: string;
37	  requirementId?: string;
38	  compact?: boolean;
39	}) {
40	  const [timeline, setTimeline] = useState<AuditTimelineEvent[]>([]);
41	  const [events, setEvents] = useState<AuditEvent[]>([]);
42	  const [error, setError] = useState<string | null>(null);
43	  const [loading, setLoading] = useState(true);
44	
45	  useEffect(() => {
46	    let cancelled = false;
47	    const filter = { scenarioId, requirementId };
48	    Promise.all([getAuditTimeline(filter), getAudit(filter)])
49	      .then(([nextTimeline, nextEvents]) => {
50	        if (cancelled) return;
51	        setTimeline(nextTimeline);
52	        setEvents(nextEvents);
53	        setError(null);
54	      })
55	      .catch((err: Error) => {
56	        if (!cancelled) setError(err.message);
57	      })
58	      .finally(() => {
59	        if (!cancelled) setLoading(false);
60	      });
61	    return () => {
62	      cancelled = true;
63	    };
64	  }, [requirementId, scenarioId]);
65	
66	  const bySeq = new Map(events.map((event) => [event.seq, event]));
67	
68	  if (loading) {
69	    return <p className="rounded-sm border border-zinc-200 dark:border-zinc-800 bg-surface p-4 text-sm text-zinc-500 dark:text-zinc-400">Loading audit trail...</p>;
70	  }
71	
72	  if (error) {
73	    return (
74	      <div className="rounded-sm border border-rose-300 bg-rose-50 p-4 text-sm text-rose-800">
75	        {error}
76	      </div>
77	    );
78	  }
79	
80	  if (timeline.length === 0) {
81	    return (
82	      <div className="rounded-sm border border-zinc-200 dark:border-zinc-800 bg-surface p-4 text-sm text-zinc-500 dark:text-zinc-400">
83	        No audit events for this selection yet.
84	      </div>
85	    );
86	  }
87	
88	  return (
89	    <div className={compact ? "space-y-3" : "space-y-4"}>
90	      {timeline.map((item) => {
91	        const event = bySeq.get(item.seq);
92	        return (
93	          <article
94	            key={item.seq}
95	            className="rounded-lg border border-zinc-200 dark:border-zinc-800 bg-surface p-4"
96	          >
97	            <div className="flex flex-wrap items-start justify-between gap-3">
98	              <div>
99	                <p className="text-sm font-semibold text-foreground">{item.sentence}</p>
100	                <p className="mt-1 text-xs text-zinc-500 dark:text-zinc-400">
101	                  #{item.seq} · {formatTime(item.ts)} · {ACTOR_LABEL[item.actor.type] ?? item.actor.type}:{" "}
102	                  {item.actor.name}
103	                </p>
104	              </div>
105	              <span className="rounded-full border border-zinc-300 dark:border-zinc-700 bg-zinc-50 dark:bg-zinc-900 px-3 py-1 text-xs font-semibold text-zinc-700 dark:text-zinc-300">
106	                {item.event_type}
107	              </span>
108	            </div>
109	            {item.rationale && <p className="mt-3 text-sm text-zinc-700 dark:text-zinc-300">{item.rationale}</p>}
110	            {event && Object.keys(event.payload ?? {}).length > 0 && (
111	              <details className="mt-3 rounded-sm border border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 p-3">
112	                <summary className="cursor-pointer text-xs font-semibold uppercase tracking-wide text-zinc-600 dark:text-zinc-400">
113	                  Before / after payload
114	                </summary>
115	                <pre className="mt-2 overflow-auto text-xs leading-relaxed text-zinc-700 dark:text-zinc-300">
116	                  {payloadPreview(event.payload)}
117	                </pre>
118	              </details>
119	            )}
120	          </article>
121	        );
122	      })}
123	    </div>
124	  );
125	}
